rule sigma 'Ransomware precursor activity' {
  description: 'Detects ransomware precursor activity.'
  metadata:
    author: 'John Doe'
    date: '2023-02-20'
  condition:
    within every process where process.name == 'powershell.exe' {
      within every command where command.line == 'vssadmin delete shadows /all' {
        alert('Ransomware precursor activity detected.')
      }
    }
}

