rule mail_forwarding_rule {
  meta:
    author = 'SOC Team'
  description = 'Detects unauthorized mailbox forwarding rules'

  strings:
    $forwarding_destination = /Gmail address/ {
      condition = 1
    }

  condition:
    any of them {
      $forwarding_destination
    }
}

